"""Гистограмма: нормальное распределение и его плотность."""
import numpy as np


def draw(fig):
    data = np.random.default_rng(1).normal(170, 8, 2000)
    x = np.linspace(data.min(), data.max(), 200)
    ax = fig.add_subplot()
    ax.hist(data, bins=30, density=True, alpha=0.7)
    ax.plot(x, np.exp(-((x - 170) ** 2) / (2 * 8 ** 2)) / (8 * np.sqrt(2 * np.pi)), "k")
    ax.set_title("Рост, см")


if __name__ == "__main__":
    from mpldemo import run
    run(draw)
